args.content:
SELECT ?item ?itemLabel ?coord
WHERE {
  ?item wdt:P31 wd:Q1764999 .
  ?item wdt:P17 wd:Q29 .
  ?item wdt:P625 ?coord .

  SERVICE wikibase:label {
    bd:serviceParam wikibase:language "[AUTO_VALUE],en" .
  }
}

